-- update_movies_60.sql
-- Replaces the movie catalog with 60 movies: 30 Hollywood + 30 Bollywood
-- across 10 genres each. Run this on your existing movie_booking DB.
-- ==========================================================

SET FOREIGN_KEY_CHECKS = 0;
DELETE FROM reviews;
DELETE FROM booking_seats;
DELETE FROM bookings;
DELETE FROM shows;
DELETE FROM movies;
ALTER TABLE movies AUTO_INCREMENT = 1;
SET FOREIGN_KEY_CHECKS = 1;

